        // ── Global keyboard shortcuts ─────────────────────────────────────────
        private void MainWindow_PreviewKeyDown(object sender, System.Windows.Input.KeyEventArgs e)
        {
            bool ctrl = (System.Windows.Input.Keyboard.Modifiers & System.Windows.Input.ModifierKeys.Control) != 0;

            // Ctrl+F — focus search box for current panel
            if (ctrl && e.Key == System.Windows.Input.Key.F)
            {
                var box = _currentPanel switch
                {
                    "Drivers"   => TxtDriverSearch  as System.Windows.Controls.TextBox,
                    "Events"    => TxtSearch         as System.Windows.Controls.TextBox,
                    "Processes" => TxtProcSearch     as System.Windows.Controls.TextBox,
                    "Apps"      => TxtAppSearch      as System.Windows.Controls.TextBox,
                    "Services"  => TxtSvcSearch      as System.Windows.Controls.TextBox,
                    "Startup"   => TxtStartupSearch  as System.Windows.Controls.TextBox,
                    _           => null
                };
                if (box != null) { box.Focus(); box.SelectAll(); e.Handled = true; return; }
            }

            // Escape — close driver detail card
            if (e.Key == System.Windows.Input.Key.Escape)
            {
                if (_currentPanel == "Drivers" && DriverDetailCard?.Visibility == Visibility.Visible)
                { HideDriverDetailCard(); e.Handled = true; return; }
            }

            // F5 — rescan/refresh current panel
            if (e.Key == System.Windows.Input.Key.F5)
            {
                switch (_currentPanel)
                {
                    case "Drivers":   DriverScan_Click(this, new RoutedEventArgs());  e.Handled = true; return;
                    case "Events":    ScanEvents_Click(this, new RoutedEventArgs());  e.Handled = true; return;
                    case "Processes": _ = RefreshProcessesAsync();                    e.Handled = true; return;
                    case "Services":  _ = LoadKeyServicesAsync();                     e.Handled = true; return;
                    case "Network":   _ = LoadNetworkAsync();                         e.Handled = true; return;
                    case "Disk":      _ = LoadDisksInternalAsync();                   e.Handled = true; return;
                    case "Ram":       _ = NavigateTo("Ram");                     e.Handled = true; return;
                    case "Battery":   _ = LoadBatteryAsync();                         e.Handled = true; return;
                    case "Apps":      _ = LoadAppsInternalAsync();                    e.Handled = true; return;
                    case "Startup":   _ = LoadStartupAsync();                         e.Handled = true; return;
                    case "Crash":     _ = LoadCrashesInternalAsync();                 e.Handled = true; return;
                }
            }

            // Ctrl+E — export CSV for current panel
            if (ctrl && e.Key == System.Windows.Input.Key.E)
            {
                switch (_currentPanel)
                {
                    case "Events":  ExportEvents_Click(this, new RoutedEventArgs());      e.Handled = true; return;
                }
            }
        }

        // ── Custom caption buttons (minimize/maximize/close) ──────────────────
        // They replace the native DWM buttons (UseAeroCaptionButtons), which do not render on all systems — see WindowChrome in
        // MainWindow.xaml.
        private void BtnCaptionMinimize_Click(object sender, RoutedEventArgs e)
        {
            WindowState = WindowState.Minimized;
        }

        private void BtnCaptionMaximize_Click(object sender, RoutedEventArgs e)
        {
            WindowState = WindowState == WindowState.Maximized
                ? WindowState.Normal
                : WindowState.Maximized;
        }

        private void BtnCaptionClose_Click(object sender, RoutedEventArgs e)
        {
            Close();
        }

        /// <summary>Syncs the glyph and tooltip of the Maximize/Restore button with the real window state — called from
        /// StateChanged (all transitions: taskbar restore, Win+Up/Down, snap layouts, double click on the title) and once at
        /// start, for the initial state.</summary>
        private void SyncCaptionMaximizeGlyph()
        {
            if (BtnCaptionMaximize == null) return;
            bool isMax = WindowState == WindowState.Maximized;
            // Segoe MDL2 Assets: E922 = Maximize, E923 = ChromeRestore
            BtnCaptionMaximize.Content = isMax ? "\uE923" : "\uE922";
            BtnCaptionMaximize.ToolTip = isMax ? "Restore" : "Maximize";
        }
    }
